?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planes y módulos</title></head><body><?php include 'header.php'; ?>
<link rel="stylesheet" href="/resources/css/central-config.css?v=20261012-1">
<style>
.pm-page{max-width:1250px;margin:24px auto 55px;padding:0 18px;font-family:Inter,"Segoe UI",Arial,sans-serif;color:#0a2945}.pm-hero{display:flex;align-items:center;gap:15px;padding:22px 25px;border-radius:20px;color:#fff;background:linear-gradient(115deg,#092e50,#087bab 60%,#10a9cc);box-shadow:0 16px 38px rgba(9,46,80,.2)}.pm-hero i{display:grid;width:56px;height:56px;place-items:center;border-radius:16px;background:rgba(255,255,255,.15);font-size:24px}.pm-hero h1{margin:0;font-size:27px;font-weight:900}.pm-hero p{margin:4px 0 0;color:#d9f4ff}.pm-toolbar,.pm-card{margin-top:18px;border:1px solid #cce3ef;border-radius:18px;background:#fff;box-shadow:0 12px 32px rgba(9,46,80,.08)}.pm-toolbar{display:grid;padding:18px;grid-template-columns:minmax(220px,1fr) auto auto;gap:10px;align-items:end}.pm-field label{display:block;margin-bottom:6px;font-size:12px;font-weight:850}.pm-field select{width:100%;height:46px;padding:0 13px;border:1px solid #bcdcee;border-radius:11px;background:#fbfdff}.pm-btn{height:46px;padding:0 17px;border:0;border-radius:11px;color:#fff;font-weight:850;cursor:pointer}.pm-new{background:#7841dc}.pm-save{background:#09aa67}.pm-card{padding:20px}.pm-summary{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.pm-summary b{font-size:18px}.pm-summary span{padding:7px 11px;border-radius:999px;color:#08734c;background:#dcf8eb;font-size:12px;font-weight:850}.pm-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.pm-group{overflow:hidden;border:1px solid #cfe4ee;border-radius:15px;background:#f8fcfe}.pm-group-head{display:flex;align-items:center;gap:10px;padding:14px 16px;color:#fff;background:linear-gradient(110deg,#0b4c79,#0b91bd)}.pm-group-head input,.pm-item input{width:19px;height:19px;accent-color:#12b76a}.pm-group-head strong{font-size:15px}.pm-items{display:grid;padding:8px 13px}.pm-item{display:flex;align-items:center;gap:10px;padding:10px 5px;border-bottom:1px solid #e1eef4}.pm-item:last-child{border:0}.pm-item span{font-size:13px;font-weight:700}.pm-toast{position:fixed;right:22px;bottom:22px;z-index:9999;padding:14px 18px;border-radius:11px;color:#fff;background:#092e50;opacity:0;transform:translateY(60px);transition:.2s}.pm-toast.show{opacity:1;transform:none}.pm-toast.error{background:#c52d43}@media(max-width:760px){.pm-toolbar,.pm-grid{grid-template-columns:1fr}.pm-btn{width:100%}}
</style>
<main class="pm-page"><header class="pm-hero"><i class="fa fa-th-large"></i><div><h1>Planes y módulos</h1><p>Habilita los menús y submenús disponibles para cada plan.</p></div></header><section class="pm-toolbar"><div class="pm-field"><label>Plan que desea configurar</label><select id="planSelect"></select></div><button class="pm-btn pm-new" id="newPlan"><i class="fa fa-plus"></i> Nuevo plan</button><button class="pm-btn pm-save" id="savePlan"><i class="fa fa-save"></i> Guardar y activar</button></section><section class="pm-card"><div class="pm-summary"><b>Módulos disponibles</b><span id="counter"></span></div><div class="pm-grid" id="menuGrid"></div></section></main><div class="pm-toast" id="toast"></div>
<script>
(function(){const csrf=<?php echo json_encode($_SESSION['planes_menu_csrf']); ?>;let plans=<?php echo json_encode($planes,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,active=<?php echo json_encode($activo); ?>;const select=document.getElementById('planSelect'),grid=document.getElementById('menuGrid');
const clean=v=>String(v||'').replace(/\s+/g,' ').trim();const key=a=>{try{const u=new URL(a.href,location.href);return u.origin===location.origin?u.pathname.toLowerCase():u.href.toLowerCase()}catch(e){return String(a.getAttribute('href')||'').toLowerCase()}};
const catalog=Array.from(document.querySelectorAll('#navBar #myNavbar>ul>li.dropdown')).map(group=>{const toggle=group.querySelector(':scope>a.dropdown-toggle'),menu=group.querySelector(':scope>ul.dropdown-menu');if(!toggle||!menu)return null;return{name:clean(toggle.textContent),items:Array.from(menu.querySelectorAll(':scope>li>a[href]')).map(a=>({name:clean(a.textContent)||a.title||key(a),key:key(a)})).filter(x=>x.key&&!x.key.includes('seg_planesmenu.php'))}}).filter(g=>g&&g.items.length);const crmLink=document.querySelector('#navBar .crm-nav-item>a[href]');if(crmLink)catalog.push({name:'CRM',items:[{name:'Acceso al CRM',key:key(crmLink)}]});
function toast(m,e){const x=document.getElementById('toast');x.textContent=m;x.className='pm-toast show'+(e?' error':'');setTimeout(()=>x.className='pm-toast',3000)}
function options(){select.innerHTML=Object.keys(plans).map(n=>`<option ${n===active?'selected':''}>${n.replace(/[&<>"']/g,'')}</option>`).join('')}
function render(){active=select.value;const p=plans[active]||{disabled:[],disabled_groups:[]};grid.innerHTML=catalog.map(g=>{const groupOff=p.disabled_groups.includes(g.name.toLowerCase());return `<section class="pm-group"><label class="pm-group-head"><input class="pm-group-check" data-group="${g.name.toLowerCase()}" type="checkbox" ${groupOff?'':'checked'}><strong>${g.name}</strong></label><div class="pm-items">${g.items.map(i=>`<label class="pm-item"><input class="pm-item-check" data-group="${g.name.toLowerCase()}" data-key="${i.key}" type="checkbox" ${!groupOff&&!p.disabled.includes(i.key)?'checked':''}><span>${i.name}</span></label>`).join('')}</div></section>`}).join('');bind();count()}
function bind(){grid.querySelectorAll('.pm-group-check').forEach(c=>c.onchange=()=>{grid.querySelectorAll(`.pm-item-check[data-group="${CSS.escape(c.dataset.group)}"]`).forEach(i=>i.checked=c.checked);count()});grid.querySelectorAll('.pm-item-check').forEach(c=>c.onchange=count)}function count(){const all=grid.querySelectorAll('.pm-item-check'),on=grid.querySelectorAll('.pm-item-check:checked');document.getElementById('counter').textContent=`${on.length} de ${all.length} habilitados`}
function capture(){plans[active]={disabled:Array.from(grid.querySelectorAll('.pm-item-check:not(:checked)')).map(x=>x.dataset.key),disabled_groups:Array.from(grid.querySelectorAll('.pm-group-check:not(:checked)')).map(x=>x.dataset.group)}}
select.onchange=()=>{capture();active=select.value;render()};document.getElementById('newPlan').onclick=()=>{const n=clean(prompt('Nombre del nuevo plan:'));if(!n)return;if(plans[n])return toast('Ese plan ya existe.',true);capture();plans[n]={disabled:[],disabled_groups:[]};active=n;options();render()};document.getElementById('savePlan').onclick=async()=>{capture();const fd=new FormData();fd.append('csrf',csrf);fd.append('plan_activo',active);fd.append('planes_json',JSON.stringify(plans));try{const r=await fetch('../controllers/PlanesMenuGuardar.php',{method:'POST',body:fd}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo guardar');toast(d.message);setTimeout(()=>location.reload(),700)}catch(e){toast(e.message,true)}};options();render();
})();
</script></body></html>
